test('S12 cleanup TEST-only', async () => {
  const deleted = []
  let reads = 0
  const client = {
    from() {
      const state = { filters: [] }
      const chain = {
        select() { return chain },
        in(column, values) { state.filters.push([column, values]); return chain },
        delete() { state.action = 'delete'; return chain },
        range() { return chain },
        then(resolve) {
          if (state.action === 'delete') {
            deleted.push(state)
            return resolve({ error: null })
          }
          reads += 1
          return resolve({
            data: reads === 1 ? [
              { id: 'keep', code: 'LOCAL_KEEP' },
              { id: 'guitar', code: 'TEST_GUITAR' },
              { id: 'piano', code: 'TEST_PIANO' },
            ] : [],
            error: null,
          })
        },
      }
      return chain
    },
  }
  const result = await run({
    mode: 'cleanup',
    url: 'http://127.0.0.1:54321',
    key: 'local-test-key',
    log() {},
    client,
  })
  assert.equal(result.removed, 2)
  assert.equal(deleted.length, 1)
  assert.deepEqual(deleted[0].filters, [
    ['id', ['guitar', 'piano']],
    ['code', TEST_CODES],
  ])
})

